"""Explain per-object flags, conditional tests and stack depot deduplication."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1885': ('검사 도구를 기록하려다가 기록 도구가 다시 검사를 부르면 같은 길을 빙빙 돌 수 있어요. 그래서 검사 도구의 빌드에서는 특정 추적 옵션을 빼요.', '함수 추적 옵션 제거와 실제 추적 실행을 구별합니다.', '여섯 runtime 객체 옆에 CFLAGS_REMOVE→CC_FLAGS_FTRACE를 적고 빌드 단계의 규칙이라고 표시하세요.', ['ftrace는 커널의 함수 호출 등을 추적하는 기능이에요. 함수를 시작할 때 기록용 코드를 거치도록 만들 수 있어요. 이런 코드를 추가하는 것을 계측이라고 불러요.', 'KMSAN runtime은 검사 기능을 실제로 수행하는 코드예요. 여기에 추적 코드를 붙이면 검사 중 추적이 시작되고 다시 검사로 돌아오는 재귀 경로가 생길 수 있어요. 원문은 재귀를 피하려고 ftrace를 끈다고 설명해요.', 'Makefile에는 CFLAGS_REMOVE_core.o = $(CC_FLAGS_FTRACE)처럼 쓴 줄이 있어요. CFLAGS_REMOVE는 해당 객체를 만들 때 빼야 할 컴파일 옵션을 지정해요. 괄호 안 변수는 추적에 사용하는 옵션 목록이에요.', '같은 제거 지정이 core, hooks, init, instrumentation, report, shadow 여섯 객체에 있어요. 객체는 소스를 컴파일해 만든 중간 결과 파일이에요. 모든 헤더 검색 경로나 모든 옵션을 지우는 규칙이 아니에요.', '뒤의 CFLAGS_core.o 같은 변수는 객체에 사용할 추가 옵션을 정하고, CFLAGS_REMOVE_core.o는 제거할 옵션을 정해요. 상위 Kbuild 규칙이 목록을 모으고 제거 규칙을 적용해 실제 명령에 사용할 옵션을 만들어요.', '제거 목록을 읽거나 펼쳐 보는 검사는 빌드 정책 확인이에요. 실제 커널에서 모든 함수를 추적해 보거나 재귀 상황을 재현했다는 뜻은 아니에요. 설정, 만들어진 코드, 실행 결과는 구별해서 확인해야 해요.'], [('여섯 객체의 CFLAGS_REMOVE가 제거 대상으로 지정하는 것은 무엇인가요?', ['언제나 모든 헤더 검색 경로예요', 'CC_FLAGS_FTRACE의 옵션들이에요'], '정답은 두 번째예요. 오른쪽 변수 이름이 무엇인지 보세요. ftrace 관련 옵션 제거이지 컴파일에 필요한 모든 경로를 지우는 것은 아니에요.'), ('제거 변수의 내용을 확인하면 실제 ftrace 실행까지 검증한 건가요?', ['아니요. 어떤 빌드 옵션을 뺄지 확인한 것이에요', '네. 모든 실제 함수 추적을 실행한 것이에요'], '정답은 첫 번째예요. 만드는 규칙을 확인하는 일과 실행 중 추적하는 일은 달라요. 실제 실행 여부를 목록 확인으로 대신할 수는 없어요.')]), 'os1886': ('여섯 부품에 같은 작업 지시서를 붙이려면 각 부품 이름에 지시서를 연결해야 해요. 공통 목록이 있다고 모든 대상에 저절로 붙는 것은 아니에요.', '객체별 공통 옵션 지정과 상위 빌드 규칙을 이해합니다.', 'core·hooks·init·instrumentation·report·shadow 여섯 이름을 쓰고 공통 runtime 옵션으로 각각 연결하세요.', ['CC_FLAGS_KMSAN_RUNTIME은 KMSAN 내부 코드를 만들 때 사용할 공통 컴파일 옵션 목록이에요. 목록에는 스택 보호 계측 제외, 지원 여부에 따른 옵션, 분기 기록을 끄는 전처리 정의가 들어가요.', '이 Makefile은 CFLAGS_core.o := $(CC_FLAGS_KMSAN_RUNTIME)처럼 각 객체의 옵션 변수에 공통 목록을 넣어요. :=는 이 자리에서 값을 펼쳐 대입하는 Make 문법이에요. C 함수가 실행 중 대입하는 문장은 아니에요.', '같은 형태가 hooks, init, instrumentation, report, shadow에도 있어요. 따라서 core와 shadow가 여기서 서로 반대되는 검사 정책을 받는 것이 아니라 같은 공통 옵션 값을 받아요.', '이 여섯 줄은 대상별 지정이라 이름이 빠지거나 틀리면 의도한 객체에 적용되지 않을 수 있어요. 빌드 객체 목록과 옵션 지정 목록을 나란히 비교하면 적용 누락을 찾는 데 도움이 돼요.', '객체별 CFLAGS만이 최종 컴파일 옵션의 전부는 아니에요. scripts/Makefile.lib 같은 상위 Kbuild 규칙이 전체·디렉터리·객체 옵션과 제거 목록을 조합해요. 이 파일의 대입과 실제 명령 구성을 연결해서 읽어요.', '따라서 공통 값을 받는다고 컴파일 명령 전체가 모든 파일에서 완전히 같다는 뜻은 아니에요. 소스 파일 이름 등 다른 요소도 있어요. 이 수업은 여섯 객체에 공통 runtime 옵션이 지정된다는 범위를 확인해요.'], [('CFLAGS_core.o와 CFLAGS_shadow.o는 이 Makefile에서 무엇을 받나요?', ['언제나 서로 반대되는 옵션을 받아요', '같은 CC_FLAGS_KMSAN_RUNTIME 값을 받아요'], '정답은 두 번째예요. 두 줄의 오른쪽이 같아요. 나머지 네 객체에도 같은 지정이 있지만 최종 명령 전체가 같다는 뜻으로 넓히지는 마세요.'), ('객체별 옵션이 실제 컴파일 명령에 들어가는 방법은 어디서 더 확인하나요?', ['상위 Kbuild의 옵션 조합 규칙에서 확인해요', 'C 프로그램이 실행 중 Makefile을 직접 실행해요'], '정답은 첫 번째예요. Makefile 변수는 빌드 단계에서 처리돼요. 소스를 실행하는 단계와 컴파일 명령을 만드는 단계를 구별하세요.')]), 'os1887': ('검사하는 기계와 그 기계가 문제를 잘 찾는지 확인할 시험 재료는 다르게 준비해요. 테스트 파일에는 검사 코드를 다시 넣어요.', '설정에 따른 테스트 객체 선택과 개별 계측 재활성화를 이해합니다.', 'CONFIG 값에 y와 n을 각각 대입해 obj-y와 obj-n 두 이름을 만들고 테스트 파일 위치를 적으세요.', ['KUnit은 커널 코드를 작은 단위로 시험하는 체계예요. kmsan_test.o는 KMSAN 동작을 확인하는 테스트 객체예요. 검사 기능을 제공하는 runtime과 검사를 받는 테스트 코드는 역할이 달라요.', 'obj-$(CONFIG_KMSAN_KUNIT_TEST) += kmsan_test.o에서 괄호 안 설정값을 변수 이름에 넣어요. 값이 y라면 obj-y에 테스트 이름을 추가해요. 기존 여섯 runtime 객체에 이 테스트가 더해지는 거예요.', '값을 n으로 둔 모형에서는 obj-n에 추가되므로 obj-y에는 들어가지 않아요. 실제 설정 파일에서 미설정 값이 빈 문자열인 경우에는 obj-가 될 수 있어요. 어느 경우든 이 규칙만으로 테스트가 무조건 obj-y에 들어가는 것은 아니에요.', '디렉터리의 기본 KMSAN_SANITIZE는 n이지만 KMSAN_SANITIZE_kmsan_test.o := y는 테스트 객체에 개별적으로 검사를 켜요. 일반 runtime에 계측을 피하는 정책과 시험용 코드에 계측하는 정책을 구별하세요.', '다음 줄은 cc-disable-warning 도우미로 uninitialized 컴파일 경고를 끌 수 있는 옵션을 추가해요. 이 테스트는 미준비 값 탐지를 시험하므로 그런 코드에 대한 컴파일 경고와 실제 KMSAN 탐지는 다른 층이에요. 모든 컴파일 경고나 런타임 검사를 끈다는 뜻은 아니에요.', '이 규칙을 읽는 것과 테스트를 실제 커널에서 실행해 통과하는 것은 달라요. 설정에 따라 어떤 객체와 계측이 선택되는지를 먼저 확인하고, 실제 실행 결과는 별도로 봐야 해요.'], [('설정값을 문자 n으로 둔 모형에서 kmsan_test.o는 obj-y에 들어가나요?', ['네. 설정과 상관없이 항상 obj-y에 들어가요', '아니요. 이때 확장한 변수 이름은 obj-n이에요'], '정답은 두 번째예요. obj- 뒤에 설정값 n을 붙이면 obj-n이에요. y일 때의 obj-y와 다르며 실제 미설정의 빈 값도 따로 구별하세요.'), ('테스트 객체의 KMSAN_SANITIZE 개별 값은 무엇인가요?', ['y로 검사를 다시 켜요', '디렉터리의 n만 적용하고 개별 값은 없어요'], '정답은 첫 번째예요. 파일 이름을 붙인 변수에 y가 명시되어 있어요. 검사 도구 자체와 검사받을 시험 코드를 같은 대상으로 보면 안 돼요.')]), 'os1888': ('같은 길 안내문을 물건마다 새로 복사하면 종이가 많이 필요해요. 안내문 하나를 보관하고 번호만 나눠 주면 중복을 줄일 수 있어요.', '호출 경로 공유와 해시 후보 검색·정확한 비교를 이해합니다.', '경로 [A,B,C]를 두 번 적고 하나의 기록 번호 H로 연결하세요. 같은 해시의 [A,B,D]는 다른 기록으로 남기세요.', ['stack trace는 함수들이 어떤 경로로 호출됐는지 나타내는 주소 배열이에요. frame은 그 배열의 한 항목이에요. 많은 메모리 객체가 같은 경로에서 만들어지면 같은 주소 배열을 반복해서 저장하게 될 수 있어요.', 'stack depot은 이런 경로를 보관하는 저장소예요. 같은 기록을 공유하고 handle이라는 작은 번호로 찾아가게 해 중복 저장을 줄여요. 번호 자체에 모든 호출 주소가 들어 있다는 뜻은 아니에요.', '저장할 경로에서 hash 값을 계산해 후보 기록이 있는 bucket을 찾아요. hash는 긴 자료를 작은 값으로 요약한 검색용 값이고 bucket은 후보들을 모은 칸이에요. 빠르게 찾아볼 범위를 줄이는 데 써요.', '서로 다른 배열이 같은 hash를 가질 수도 있어요. 이를 해시 충돌이라고 해요. find_stack은 hash뿐 아니라 항목 수도 비교하고, 실제 배열 내용도 비교해요. 같은 요약값이라는 이유만으로 경로를 합치지 않아요.', '정상적으로 저장된 [A,B,C]가 남아 있는 상태에서 같은 세 항목을 다시 저장하면 기존 기록을 찾아 같은 handle을 돌려줄 수 있어요. [A,B,D]는 같은 hash여도 내용이 달라 별도 기록이 필요해요. A·B·C·D는 설명용 주소 이름이에요.', '실제 저장 경로는 처음 검색한 뒤 필요하면 잠금을 얻고 다시 검색해요. 그사이 다른 실행이 같은 경로를 넣었을 수 있어서 중복 추가를 피하려는 거예요. 할당 실패나 기록 수명 등의 조건도 있으므로 임의의 입력과 모든 시점에서 항상 같은 번호를 보장한다고 넓히지 마세요.'], [('서로 다른 주소 배열의 hash가 같으면 즉시 같은 기록으로 합치나요?', ['네. hash 하나만 같으면 무조건 같아요', '아니요. 항목 수와 실제 주소 배열 내용도 비교해요'], '정답은 두 번째예요. 해시는 후보 찾기용이라 충돌할 수 있어요. 같은 반 번호라고 같은 학생이 아닌 것처럼 실제 내용을 더 확인해야 해요.'), ('정상 저장이 성공하고 기록이 유지되는 모형에서 [A,B,C]를 두 번 저장하면 어떻게 되나요?', ['같은 기록을 찾아 같은 handle을 돌려줘요', '반드시 서로 다른 기록 두 개를 만들어요'], '정답은 첫 번째예요. 이미 있는 정확한 경로를 공유하는 것이 중복 제거예요. 다만 실패나 기록 제거까지 무시한 모든 상황의 보장은 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_467.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
